      referenceIds: ["ref-kukanich-2021", "ref-isfm-aafp-2024-nsaid", "ref-bsava-nephrology-20"],
      evidenceLevel: "N\xEDvel 1b \u2014 Ensaio Cl\xEDnico Prospectivo Randomizado Placebo-Controlado (KuKanich 2021)"
