        ["Octreotida", "c\xE3o", "2\u20134 \xB5g/kg SC q8\u201312h", "Adjuvante", "(7)(23)"],
        ["Estreptozotocina", "c\xE3o", "500 mg/m\xB2 IV q3 sem", "Metast\xE1tico/recorrente", "(7)(20)(21)"],
        ["Toceranibe", "c\xE3o", "2,4\u20132,75 mg/kg PO q48h", "Terapia alvo", "(7)(15)"]
