function withPlainLanguage(record) {
  return {
    ...record,
    plainLanguage: record.plainLanguage ?? DISEASE_PLAIN_LANGUAGE[record.slug],
    relatedConsensusSlugs: mergeConsensusSlugsForDisease(record.slug, record.relatedConsensusSlugs)
  };
}
